"use client";

import { motion, useMotionValue, useSpring, useTransform } from "motion/react";
import React, { useCallback, useEffect, useId, useRef } from "react";

import { cn } from "@/lib/utils";

import { RefractionFilter } from "./refraction-filter";

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface LiquidGlassSliderProps {
  // ─────────────────────────────────────────────────────────────────────────
  // Value Control
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Current value of the slider (controlled mode).
   * If provided, the slider becomes controlled.
   */
  value?: number;

  /**
   * Default value of the slider (uncontrolled mode).
   * @default 10
   */
  defaultValue?: number;

  /**
   * Minimum value of the slider.
   * @default 0
   */
  min?: number;

  /**
   * Maximum value of the slider.
   * @default 100
   */
  max?: number;

  /**
   * Step size for value changes.
   * @default 1
   */
  step?: number;

  /**
   * Callback triggered when the slider value changes.
   */
  onChange?: (value: number) => void;

  /**
   * Callback triggered when dragging starts.
   */
  onDragStart?: () => void;

  /**
   * Callback triggered when dragging ends.
   */
  onDragEnd?: () => void;

  // ─────────────────────────────────────────────────────────────────────────
  // Appearance
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Additional CSS classes.
   */
  className?: string;

  /**
   * Width of the slider track in pixels.
   * @default 330
   */
  width?: number;

  /**
   * Color of the track fill (progress portion).
   * @default "#0377F7"
   */
  fillColor?: string;

  /**
   * Color of the track background.
   * @default "#89898F66"
   */
  trackColor?: string;

  /**
   * Color of the thumb when not pressed.
   * @default "rgba(255, 255, 255, 1)"
   */
  thumbColor?: string;

  /**
   * Whether the slider is disabled.
   * @default false
   */
  disabled?: boolean;

  // ─────────────────────────────────────────────────────────────────────────
  // Optical Parameters (Advanced)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Blur level for the glass refraction effect.
   * @default 0
   */
  blur?: number;

  /**
   * Opacity of the specular highlight.
   * @default 0.4
   */
  specularOpacity?: number;

  /**
   * Saturation multiplier for the specular highlight.
   * @default 7
   */
  specularSaturation?: number;

  /**
   * Base refraction level (controls magnification intensity).
   * @default 1
   */
  refractionLevel?: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A sleek liquid glass slider with iOS 26-inspired refraction effects.
 *
 * @example
 * ```tsx
 * <LiquidGlassSlider
 *   defaultValue={50}
 *   onChange={(value) => console.log("Value:", value)}
 * />
 * ```
 *
 * @example Custom colors
 * ```tsx
 * <LiquidGlassSlider
 *   fillColor="#22c55e"
 *   trackColor="#14532d44"
 * />
 * ```
 */
export const LiquidGlassSlider: React.FC<LiquidGlassSliderProps> = ({
  // Value Control
  value: controlledValue,
  defaultValue = 10,
  min = 0,
  max = 100,
  step = 1,
  onChange,
  onDragStart,
  onDragEnd,
  // Appearance
  className,
  width = 330,
  fillColor = "#0377F7",
  trackColor = "#89898F66",
  thumbColor = "rgba(255, 255, 255, 1)",
  disabled = false,
  // Optical Parameters
  blur = 0,
  specularOpacity = 0.4,
  specularSaturation = 7,
  refractionLevel = 1,
}) => {
  const filterId = useId();
  const isControlled = controlledValue !== undefined;

  // ─────────────────────────────────────────────────────────────────────────
  // Dimensions
  // ─────────────────────────────────────────────────────────────────────────
  const sliderHeight = 14;
  const thumbWidth = 90;
  const thumbHeight = 60;
  const thumbRadius = 30;
  const SCALE_REST = 0.6;
  const SCALE_DRAG = 1;
  const thumbWidthRest = thumbWidth * SCALE_REST;

  // ─────────────────────────────────────────────────────────────────────────
  // Motion Values
  // ─────────────────────────────────────────────────────────────────────────
  const internalValue = useMotionValue(defaultValue);
  const pointerDown = useMotionValue(0);

  // Refs
  const trackRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);

  // Sync controlled value
  useEffect(() => {
    if (isControlled && controlledValue !== undefined) {
      internalValue.set(controlledValue);
    }
  }, [controlledValue, isControlled, internalValue]);

  // ─────────────────────────────────────────────────────────────────────────
  // Derived Motion Values
  // ─────────────────────────────────────────────────────────────────────────
  const isUp = useTransform((): number => (pointerDown.get() > 0.5 ? 1 : 0));

  const pressMultiplier = useTransform(isUp, [0, 1], [0.4, 0.9]);
  const scaleRatio = useSpring(
    useTransform([pressMultiplier], ([m]) => (Number(m) || 0) * refractionLevel)
  );

  const scaleSpring = useSpring(
    useTransform(isUp, [0, 1], [SCALE_REST, SCALE_DRAG]),
    { damping: 80, stiffness: 2000 }
  );

  const backgroundOpacity = useSpring(useTransform(isUp, [0, 1], [1, 0.1]), {
    damping: 80,
    stiffness: 2000,
  });

  const fillWidth = useTransform(internalValue, (v) => {
    const percent = ((v - min) / (max - min)) * 100;
    return `${Math.max(0, Math.min(100, percent))}%`;
  });

  const thumbX = useTransform(internalValue, (v) => {
    const percent = (v - min) / (max - min);
    const range = width - thumbWidth + thumbWidthRest / 1.5;
    return percent * range - thumbWidthRest / 3;
  });

  // ─────────────────────────────────────────────────────────────────────────
  // Pointer Release Handler
  // ─────────────────────────────────────────────────────────────────────────
  useEffect(() => {
    function onPointerUp() {
      pointerDown.set(0);
    }
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("mouseup", onPointerUp);
    window.addEventListener("touchend", onPointerUp);
    return () => {
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("mouseup", onPointerUp);
      window.removeEventListener("touchend", onPointerUp);
    };
  }, [pointerDown]);

  // ─────────────────────────────────────────────────────────────────────────
  // Value Update Handler
  // ─────────────────────────────────────────────────────────────────────────
  const updateValue = useCallback(
    (newValue: number) => {
      const steppedValue = Math.round(newValue / step) * step;
      const clampedValue = Math.max(min, Math.min(max, steppedValue));

      if (!isControlled) {
        internalValue.set(clampedValue);
      }
      onChange?.(clampedValue);
    },
    [min, max, step, isControlled, onChange, internalValue]
  );

  // ─────────────────────────────────────────────────────────────────────────
  // Drag Handlers
  // ─────────────────────────────────────────────────────────────────────────
  const handleDrag = useCallback(() => {
    if (!trackRef.current || !thumbRef.current) return;

    const track = trackRef.current.getBoundingClientRect();
    const thumb = thumbRef.current.getBoundingClientRect();

    const x0 = track.left + thumbWidthRest / 2;
    const x100 = track.right - thumbWidthRest / 2;
    const trackInsideWidth = x100 - x0;
    const thumbCenterX = thumb.left + thumb.width / 2;
    const x = Math.max(x0, Math.min(x100, thumbCenterX));
    const ratio = (x - x0) / trackInsideWidth;

    updateValue(ratio * (max - min) + min);
  }, [max, min, thumbWidthRest, updateValue]);

  const handleTrackClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (disabled || !trackRef.current) return;

      const rect = trackRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const ratio = x / rect.width;
      updateValue(ratio * (max - min) + min);
    },
    [disabled, max, min, updateValue]
  );

  // ─────────────────────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────────────────────
  return (
    <div
      className={cn(
        "relative select-none",
        disabled && "pointer-events-none opacity-50",
        className
      )}
      style={{
        width,
        height: thumbHeight,
      }}
    >
      {/* Track */}
      <motion.div
        ref={trackRef}
        style={{
          width,
          height: sliderHeight,
          left: 0,
          top: (thumbHeight - sliderHeight) / 2,
          backgroundColor: trackColor,
          borderRadius: sliderHeight / 2,
          position: "absolute",
          cursor: disabled ? "not-allowed" : "pointer",
        }}
        onClick={handleTrackClick}
        onMouseDown={() => !disabled && pointerDown.set(1)}
        onMouseUp={() => pointerDown.set(0)}
      >
        {/* Fill */}
        <div className="h-full w-full overflow-hidden rounded-full">
          <motion.div
            style={{
              height: sliderHeight,
              width: fillWidth,
              borderRadius: 6,
              backgroundColor: fillColor,
            }}
          />
        </div>
      </motion.div>

      {/* Refraction Filter */}
      <RefractionFilter
        id={filterId}
        width={thumbWidth}
        height={thumbHeight}
        radius={thumbRadius}
        bezelWidth={16}
        glassThickness={80}
        bezelType="convex_squircle"
        refractiveIndex={1.45}
        blur={blur}
        scaleRatio={scaleRatio}
        specularOpacity={specularOpacity}
        specularSaturation={specularSaturation}
      />

      {/* Thumb */}
      <motion.div
        ref={thumbRef}
        drag={disabled ? false : "x"}
        dragConstraints={{
          left: -thumbWidthRest / 3,
          right: width - thumbWidth + thumbWidthRest / 3,
        }}
        dragElastic={0.02}
        dragMomentum={false}
        onMouseDown={() => !disabled && pointerDown.set(1)}
        onMouseUp={() => pointerDown.set(0)}
        onDragStart={() => {
          pointerDown.set(1);
          onDragStart?.();
        }}
        onDrag={handleDrag}
        onDragEnd={() => {
          pointerDown.set(0);
          onDragEnd?.();
        }}
        className="absolute"
        style={{
          height: thumbHeight,
          width: thumbWidth,
          top: 0,
          x: thumbX,
          borderRadius: thumbRadius,
          backdropFilter: `url(#${filterId})`,
          scale: scaleSpring,
          cursor: disabled ? "not-allowed" : "pointer",
          backgroundColor: useTransform(backgroundOpacity, (op) =>
            thumbColor.replace(/[\d.]+\)$/, `${op})`)
          ),
          boxShadow: "0 3px 14px rgba(0,0,0,0.1)",
        }}
      />
    </div>
  );
};

export default LiquidGlassSlider;

"use client";

import { motion, type MotionValue, useTransform } from "motion/react";
import React, { useEffect, useMemo, useState } from "react";

import {
  calculateDisplacementMap,
  calculateDisplacementMap2,
} from "./lib/displacementMap";
import { calculateRefractionSpecular } from "./lib/specular";
import { CONCAVE, CONVEX, CONVEX_CIRCLE, LIP } from "./lib/surfaceEquations";

// Helper to get value from either a primitive or MotionValue
function getValueOrMotion<T>(value: T | MotionValue<T>): T {
  return value && typeof value === "object" && "get" in value
    ? (value as MotionValue<T>).get()
    : (value as T);
}

export interface RefractionFilterProps {
  id: string;
  width: number;
  height: number;
  radius: number;
  bezelWidth: number;
  glassThickness: number;
  bezelType: "convex_circle" | "convex_squircle" | "concave" | "lip";
  refractiveIndex: number;
  withSvgWrapper?: boolean;
  blur?: number | MotionValue<number>;
  scaleRatio?: number | MotionValue<number>;
  specularOpacity?: number | MotionValue<number>;
  specularSaturation?: number | MotionValue<number>;
}

interface GeneratedMaps {
  displacementMapUrl: string;
  specularMapUrl: string;
  maxDisplacement: number;
}

function imageDataToDataUrl(imageData: ImageData): string {
  const canvas = document.createElement("canvas");
  canvas.width = imageData.width;
  canvas.height = imageData.height;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Failed to get canvas context");
  ctx.putImageData(imageData, 0, 0);
  return canvas.toDataURL("image/png");
}

export const RefractionFilter: React.FC<RefractionFilterProps> = ({
  id,
  width,
  height,
  radius,
  bezelWidth,
  glassThickness,
  bezelType,
  refractiveIndex,
  withSvgWrapper = true,
  blur = 0.2,
  scaleRatio = 1,
  specularOpacity = 0.4,
  specularSaturation = 4,
}) => {
  const [maps, setMaps] = useState<GeneratedMaps | null>(null);

  // Select surface function based on bezelType
  const surfaceFn = useMemo(() => {
    switch (bezelType) {
      case "convex_circle":
        return CONVEX_CIRCLE.fn;
      case "convex_squircle":
        return CONVEX.fn;
      case "concave":
        return CONCAVE.fn;
      case "lip":
        return LIP.fn;
      default:
        return CONVEX.fn;
    }
  }, [bezelType]);

  // Generate maps on mount (client-side only)
  useEffect(() => {
    // Calculate the precomputed displacement map
    const precomputedMap = calculateDisplacementMap(
      glassThickness,
      bezelWidth,
      surfaceFn,
      refractiveIndex
    );

    const maxDisplacement = Math.max(...precomputedMap.map((x) => Math.abs(x)));

    // Generate displacement map image
    const displacementImageData = calculateDisplacementMap2(
      width,
      height,
      width,
      height,
      radius,
      bezelWidth,
      100,
      precomputedMap,
      2
    );

    // Generate specular map image
    const specularImageData = calculateRefractionSpecular(
      width,
      height,
      radius,
      bezelWidth,
      undefined,
      2
    );

    // Batch all state updates into a single setState call
    // This is intentional - we need to compute canvas-based maps on the client side
    // eslint-disable-next-line
    setMaps({
      displacementMapUrl: imageDataToDataUrl(displacementImageData),
      specularMapUrl: imageDataToDataUrl(specularImageData),
      maxDisplacement,
    });
  }, [
    width,
    height,
    radius,
    bezelWidth,
    glassThickness,
    refractiveIndex,
    surfaceFn,
  ]);

  // Calculate final scale using maxDisplacement and scaleRatio
  const scale = useTransform(() => {
    const ratio =
      typeof scaleRatio === "number" ? scaleRatio : scaleRatio.get();
    return (maps?.maxDisplacement ?? 100) * ratio;
  });

  // Convert specularSaturation to string for feColorMatrix values attribute

  const specularSaturationValue = useTransform(() =>
    getValueOrMotion(specularSaturation).toString()
  ) as any; // eslint-disable-line @typescript-eslint/no-explicit-any

  // Don't render until maps are generated
  if (!maps) {
    return null;
  }

  const content = (
    <filter id={id}>
      <motion.feGaussianBlur
        in="SourceGraphic"
        stdDeviation={blur}
        result="blurred_source"
      />
      <feImage
        href={maps.displacementMapUrl}
        x={0}
        y={0}
        width={width}
        height={height}
        result="displacement_map"
      />
      <motion.feDisplacementMap
        in="blurred_source"
        in2="displacement_map"
        scale={scale}
        xChannelSelector="R"
        yChannelSelector="G"
        result="displaced"
      />
      <motion.feColorMatrix
        in="displaced"
        type="saturate"
        values={specularSaturationValue}
        result="displaced_saturated"
      />
      <feImage
        href={maps.specularMapUrl}
        x={0}
        y={0}
        width={width}
        height={height}
        result="specular_layer"
      />
      <feComposite
        in="displaced_saturated"
        in2="specular_layer"
        operator="in"
        result="specular_saturated"
      />
      <feComponentTransfer in="specular_layer" result="specular_faded">
        <motion.feFuncA type="linear" slope={specularOpacity} />
      </feComponentTransfer>
      <feBlend
        in="specular_saturated"
        in2="displaced"
        mode="normal"
        result="withSaturation"
      />
      <feBlend in="specular_faded" in2="withSaturation" mode="normal" />
    </filter>
  );

  return withSvgWrapper ? (
    <svg colorInterpolationFilters="sRGB" style={{ display: "none" }}>
      <defs>{content}</defs>
    </svg>
  ) : (
    content
  );
};

export default RefractionFilter;

/**
 * Displacement map generation for liquid glass effect.
 * This version uses browser-native ImageData instead of Node's canvas package.
 */

export function calculateDisplacementMap(
  glassThickness: number = 200,
  bezelWidth: number = 50,
  bezelHeightFn: (x: number) => number = (x) => x,
  refractiveIndex: number = 1.5,
  samples: number = 128
): number[] {
  const eta = 1 / refractiveIndex;

  // Simplified refraction, which only handles fully vertical incident ray [0, 1]
  function refract(normalX: number, normalY: number): [number, number] | null {
    const dot = normalY;
    const k = 1 - eta * eta * (1 - dot * dot);
    if (k < 0) {
      // Total internal reflection
      return null;
    }
    const kSqrt = Math.sqrt(k);
    return [
      -(eta * dot + kSqrt) * normalX,
      eta - (eta * dot + kSqrt) * normalY,
    ];
  }

  return Array.from({ length: samples }, (_, i) => {
    const x = i / samples;
    const y = bezelHeightFn(x);

    // Calculate derivative in x
    const dx = x < 1 ? 0.0001 : -0.0001;
    const y2 = bezelHeightFn(x + dx);
    const derivative = (y2 - y) / dx;
    const magnitude = Math.sqrt(derivative * derivative + 1);
    const normal = [-derivative / magnitude, -1 / magnitude];
    const refracted = refract(normal[0], normal[1]);

    if (!refracted) {
      return 0;
    } else {
      const remainingHeightOnBezel = y * bezelWidth;
      const remainingHeight = remainingHeightOnBezel + glassThickness;

      // Return displacement (rest of travel on x-axis)
      return refracted[0] * (remainingHeight / refracted[1]);
    }
  });
}

export function calculateDisplacementMap2(
  canvasWidth: number,
  canvasHeight: number,
  objectWidth: number,
  objectHeight: number,
  radius: number,
  bezelWidth: number,
  maximumDisplacement: number,
  precomputedDisplacementMap: number[] = [],
  dpr: number = typeof window !== "undefined"
    ? (window.devicePixelRatio ?? 1)
    : 1
): ImageData {
  const bufferWidth = canvasWidth * dpr;
  const bufferHeight = canvasHeight * dpr;
  const imageData = new ImageData(bufferWidth, bufferHeight);

  // Fill neutral color using buffer
  const neutral = 0xff008080;
  new Uint32Array(imageData.data.buffer).fill(neutral);

  const radius_ = radius * dpr;
  const bezel = bezelWidth * dpr;

  const radiusSquared = radius_ ** 2;
  const radiusPlusOneSquared = (radius_ + 1) ** 2;
  const radiusMinusBezelSquared = (radius_ - bezel) ** 2;

  const objectWidth_ = objectWidth * dpr;
  const objectHeight_ = objectHeight * dpr;
  const widthBetweenRadiuses = objectWidth_ - radius_ * 2;
  const heightBetweenRadiuses = objectHeight_ - radius_ * 2;

  const objectX = (bufferWidth - objectWidth_) / 2;
  const objectY = (bufferHeight - objectHeight_) / 2;

  for (let y1 = 0; y1 < objectHeight_; y1++) {
    for (let x1 = 0; x1 < objectWidth_; x1++) {
      const idx = ((objectY + y1) * bufferWidth + objectX + x1) * 4;

      const isOnLeftSide = x1 < radius_;
      const isOnRightSide = x1 >= objectWidth_ - radius_;
      const isOnTopSide = y1 < radius_;
      const isOnBottomSide = y1 >= objectHeight_ - radius_;

      const x = isOnLeftSide
        ? x1 - radius_
        : isOnRightSide
          ? x1 - radius_ - widthBetweenRadiuses
          : 0;

      const y = isOnTopSide
        ? y1 - radius_
        : isOnBottomSide
          ? y1 - radius_ - heightBetweenRadiuses
          : 0;

      const distanceToCenterSquared = x * x + y * y;

      const isInBezel =
        distanceToCenterSquared <= radiusPlusOneSquared &&
        distanceToCenterSquared >= radiusMinusBezelSquared;

      // Only write non-neutral displacements (when isInBezel)
      if (isInBezel) {
        const opacity =
          distanceToCenterSquared < radiusSquared
            ? 1
            : 1 -
              (Math.sqrt(distanceToCenterSquared) - Math.sqrt(radiusSquared)) /
                (Math.sqrt(radiusPlusOneSquared) - Math.sqrt(radiusSquared));

        const distanceFromCenter = Math.sqrt(distanceToCenterSquared);
        const distanceFromSide = radius_ - distanceFromCenter;

        // Viewed from top
        const cos = x / distanceFromCenter;
        const sin = y / distanceFromCenter;

        const bezelIndex =
          ((distanceFromSide / bezel) * precomputedDisplacementMap.length) | 0;
        const distance = precomputedDisplacementMap[bezelIndex] ?? 0;

        const dX = (-cos * distance) / maximumDisplacement;
        const dY = (-sin * distance) / maximumDisplacement;

        imageData.data[idx] = 128 + dX * 127 * opacity; // R
        imageData.data[idx + 1] = 128 + dY * 127 * opacity; // G
        imageData.data[idx + 2] = 0; // B
        imageData.data[idx + 3] = 255; // A
      }
    }
  }
  return imageData;
}

/**
 * Specular map generation for liquid glass effect.
 * This version uses browser-native ImageData instead of Node's canvas package.
 */

export function calculateRefractionSpecular(
  objectWidth: number,
  objectHeight: number,
  radius: number,
  bezelWidth: number,
  specularAngle = Math.PI / 3,
  dpr: number = typeof window !== "undefined"
    ? (window.devicePixelRatio ?? 1)
    : 1
): ImageData {
  const bufferWidth = objectWidth * dpr;
  const bufferHeight = objectHeight * dpr;
  const imageData = new ImageData(bufferWidth, bufferHeight);

  const radius_ = radius * dpr;
  const bezel_ = bezelWidth * dpr;

  // Vector along which we should see specular
  const specular_vector = [Math.cos(specularAngle), Math.sin(specularAngle)];

  // Fill neutral color using buffer
  const neutral = 0x00000000;
  new Uint32Array(imageData.data.buffer).fill(neutral);

  const radiusSquared = radius_ ** 2;
  const radiusPlusOneSquared = (radius_ + dpr) ** 2;
  const radiusMinusBezelSquared = (radius_ - bezel_) ** 2;

  const widthBetweenRadiuses = bufferWidth - radius_ * 2;
  const heightBetweenRadiuses = bufferHeight - radius_ * 2;

  for (let y1 = 0; y1 < bufferHeight; y1++) {
    for (let x1 = 0; x1 < bufferWidth; x1++) {
      const idx = (y1 * bufferWidth + x1) * 4;

      const isOnLeftSide = x1 < radius_;
      const isOnRightSide = x1 >= bufferWidth - radius_;
      const isOnTopSide = y1 < radius_;
      const isOnBottomSide = y1 >= bufferHeight - radius_;

      const x = isOnLeftSide
        ? x1 - radius_
        : isOnRightSide
          ? x1 - radius_ - widthBetweenRadiuses
          : 0;

      const y = isOnTopSide
        ? y1 - radius_
        : isOnBottomSide
          ? y1 - radius_ - heightBetweenRadiuses
          : 0;

      const distanceToCenterSquared = x * x + y * y;

      const isInBezel =
        distanceToCenterSquared <= radiusPlusOneSquared &&
        distanceToCenterSquared >= radiusMinusBezelSquared;

      // Process pixels that are in bezel or near bezel edge for anti-aliasing
      if (isInBezel) {
        const distanceFromCenter = Math.sqrt(distanceToCenterSquared);
        const distanceFromSide = radius_ - distanceFromCenter;

        const opacity =
          distanceToCenterSquared < radiusSquared
            ? 1
            : 1 -
              (distanceFromCenter - Math.sqrt(radiusSquared)) /
                (Math.sqrt(radiusPlusOneSquared) - Math.sqrt(radiusSquared));

        // Viewed from top
        const cos = x / distanceFromCenter;
        const sin = -y / distanceFromCenter;

        // Dot product of orientation
        const dotProduct = Math.abs(
          cos * specular_vector[0] + sin * specular_vector[1]
        );

        const coefficient =
          dotProduct * Math.sqrt(1 - (1 - distanceFromSide / (1 * dpr)) ** 2);

        const color = 255 * coefficient;
        const finalOpacity = color * coefficient * opacity;

        imageData.data[idx] = color;
        imageData.data[idx + 1] = color;
        imageData.data[idx + 2] = color;
        imageData.data[idx + 3] = finalOpacity;
      }
    }
  }
  return imageData;
}

export type SurfaceFnDef = {
  title: string;
  fn: (x: number) => number;
};

export const CONVEX_CIRCLE: SurfaceFnDef = {
  title: "Convex Circle",
  fn: (x) => Math.sqrt(1 - (1 - x) ** 2),
};

export const CONVEX: SurfaceFnDef = {
  title: "Convex Squircle",
  fn: (x) => Math.pow(1 - Math.pow(1 - x, 4), 1 / 4),
};

export const CONCAVE: SurfaceFnDef = {
  title: "Concave",
  fn: (x) => 1 - CONVEX_CIRCLE.fn(x),
};

export const LIP: SurfaceFnDef = {
  title: "Lip",
  fn: (x) => {
    const convex = CONVEX.fn(x * 2);
    const concave = CONCAVE.fn(x) + 0.1;
    const smootherstep = 6 * x ** 5 - 15 * x ** 4 + 10 * x ** 3;
    return convex * (1 - smootherstep) + concave * smootherstep;
  },
};

export const fns: SurfaceFnDef[] = [CONVEX, CONCAVE, LIP];
